#include <vector>
#include <numeric>

class Solution {
public:
    int maxValidSplits(std::vector<int>& nums) {
        long long total = std::accumulate(nums.begin(), nums.end(), 0LL);
        long long running = 0;
        int splits = 0;
        for (size_t i = 0; i + 1 < nums.size(); ++i) {
            running += nums[i];
            if (running * 2 == total) {
                splits++;
            }
        }
        return splits;
    }
};

class Solution {
    public int maxValidSplits(int[] nums) {
        long total = 0;
        for (int x : nums) total += x;
        long running = 0;
        int splits = 0;
        for (int i = 0; i < nums.length - 1; i++) {
            running += nums[i];
            if (running * 2 == total) {
                splits++;
            }
        }
        return splits;
    }
}

